-- Dev question id 420 (topic: wrapper-classes, language: en)
WITH new_question_420 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'MULTIPLE_CHOICE', 'INTERMEDIATE',
           'PUBLISHED', 'OPENAI',
           $$Which of the following statements about autoboxing and autounboxing are true?$$, NULL, NULL,
           $$Both statements are correct; autoboxing automatically converts a primitive to a wrapper, while autounboxing converts a wrapper back to a primitive. This automatic conversion is what makes working with collections easier.$$, $$gentest-review-admin@example.com$$, '2026-08-31 22:47:34.768716',
           now(), now()
    FROM topic WHERE slug = 'wrapper-classes'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT id, $$Autoboxing converts a primitive value into its wrapper object.$$, TRUE, 0 FROM new_question_420
        UNION ALL SELECT id, $$Autounboxing converts a wrapper object back into its primitive value.$$, TRUE, 1 FROM new_question_420
        UNION ALL SELECT id, $$Autoboxing can only be done manually.$$, FALSE, 2 FROM new_question_420
        UNION ALL SELECT id, $$Autounboxing can lead to NullPointerExceptions if the wrapper is null.$$, TRUE, 3 FROM new_question_420;

-- Dev question id 421 (topic: wrapper-classes, language: en)
WITH new_question_421 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'SINGLE_CHOICE', 'BEGINNER',
           'PUBLISHED', 'OPENAI',
           $$What happens when you try to unbox a null wrapper in Java?$$, NULL, NULL,
           $$Unboxing a null wrapper throws a NullPointerException, which is a significant pitfall when dealing with wrapper classes. This is crucial to remember when working with methods that can return null.$$, $$n8n-ai-judge$$, '2026-08-31 22:44:57.280986',
           now(), now()
    FROM topic WHERE slug = 'wrapper-classes'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT id, $$It returns 0.$$, FALSE, 0 FROM new_question_421
        UNION ALL SELECT id, $$It throws a NullPointerException.$$, TRUE, 1 FROM new_question_421
        UNION ALL SELECT id, $$It returns null.$$, FALSE, 2 FROM new_question_421
        UNION ALL SELECT id, $$It returns an empty string.$$, FALSE, 3 FROM new_question_421;

