        UNION ALL SELECT id, $$false$$, FALSE, 1 FROM new_question_422
        UNION ALL SELECT id, $$NullPointerException$$, FALSE, 2 FROM new_question_422
        UNION ALL SELECT id, $$100$$, FALSE, 3 FROM new_question_422;

