        UNION ALL SELECT id, $$It can return true for some values and false for others.$$, TRUE, 1 FROM new_question_424
        UNION ALL SELECT id, $$It is the recommended method for all object comparisons.$$, FALSE, 2 FROM new_question_424
        UNION ALL SELECT id, $$It does not work with wrapper classes.$$, FALSE, 3 FROM new_question_424;

